  1	{
  2	  "$schema": "http://json-schema.org/draft-07/schema#",
  3	  "$id": "https://github.com/piercingxx/xx-stack/inventory.schema.json",
  4	  "title": "xx-stack inventory",
  5	  "description": "Single source of truth for hardware, network reachability, and installed inference runtimes. Consumed by xx-stack/scripts/generate-registries.mjs, which fans it out to the TypeScript platform registries and the Hermes lane config.",
  6	  "type": "object",
  7	  "required": ["version", "policy", "machines"],
  8	  "additionalProperties": false,
  9	  "properties": {
 10	    "$schema": { "type": "string" },
 11	    "version": { "const": 1 },
 12	    "_readme": {
 13	      "type": "array",
 14	      "items": { "type": "string" },
 15	      "description": "Free-form notes for humans. Ignored by the generator."
 16	    },
 17	
 18	    "policy": {
 19	      "type": "object",
 20	      "required": ["laneOrder", "cloudEscalation"],
 21	      "additionalProperties": false,
 22	      "properties": {
 23	        "selfHostedFirst": { "type": "boolean", "default": true },
 24	        "cloudEscalation": {
 25	          "type": "object",
 26	          "required": ["optIn"],
 27	          "additionalProperties": false,
 28	          "properties": {
 29	            "optIn": {
 30	              "type": "boolean",
 31	              "description": "Fail-safe. While false, routing never selects a cloud host even when every self-hosted lane is unreachable."
 32	            },
 33	            "note": { "type": "string" }
 34	          }
 35	        },
 36	        "laneOrder": {
 37	          "type": "array",
 38	          "items": { "type": "string" },
 39	          "minItems": 1,
 40	          "description": "Tier ids in preference order, e.g. local, tailscale-openai-compatible, tailscale-ollama, cloud."
 41	        },
 42	        "rules": { "type": "array", "items": { "type": "object" } }
 43	      }
 44	    },
 45	
 46	    "machines": {
 47	      "type": "array",
 48	      "description": "Physical or virtual machines you own. Describe each ONCE; every runtime installed on it becomes a separate lane automatically.",
 49	      "items": { "$ref": "#/definitions/machine" }
 50	    },
 51	
 52	    "aggregators": {
 53	      "type": "array",
 54	      "description": "Meta-endpoints that route to other lanes themselves (currently the Hermes loopback proxy) rather than serving a model directly.",
 55	      "items": { "$ref": "#/definitions/aggregator" }
 56	    },
 57	
 58	    "cloud": {
 59	      "type": "object",
 60	      "additionalProperties": false,
 61	      "properties": {
 62	        "providers": { "type": "array", "items": { "$ref": "#/definitions/cloudProvider" } },
 63	        "hermesCli": {
 64	          "type": "object",
 65	          "description": "A cloud lane Hermes reaches through a local CLI rather than an HTTP endpoint.",
 66	          "required": ["id", "provider", "endpointType", "baseUrl", "model"],
 67	          "properties": {
 68	            "id": { "type": "string" },
 69	            "provider": { "type": "string" },
 70	            "endpointType": { "const": "hermes_cli" },
 71	            "baseUrl": { "type": "string" },
 72	            "model": { "type": "string" },
 73	            "fallbackModels": { "type": "array", "items": { "type": "string" } },
 74	            "hermesPriority": { "type": "integer" },
 75	            "enabled": { "type": "boolean" },
 76	            "notes": { "type": "string" }
 77	          }
 78	        }
 79	      }
 80	    }
 81	  },
 82	
 83	  "definitions": {
 84	    "network": {
 85	      "type": "object",
 86	      "required": ["scope", "address"],
 87	      "additionalProperties": false,
 88	      "properties": {
 89	        "scope": {
 90	          "enum": ["localhost", "loopback", "tailscale", "lan", "internet"],
 91	          "description": "Drives which tier the machine's runtimes land in and whether Hermes dials it."
 92	        },
 93	        "address": {
 94	          "type": "string",
 95	          "description": "Hostname or IP. Prefer a Tailscale MagicDNS name over a raw tailnet IP so the config stays portable and does not leak your addressing."
 96	        },
 97	        "notes": { "type": "string" }
 98	      }
 99	    },
100	
101	    "hardware": {
102	      "type": "object",
103	      "additionalProperties": false,
104	      "properties": {
105	        "summary": { "type": "string" },
106	        "cpu": { "type": "string" },
107	        "ram": { "type": "string" },
108	        "gpu": {
109	          "type": "array",
110	          "items": {
111	            "type": "object",
112	            "required": ["name", "count"],
113	            "additionalProperties": false,
114	            "properties": {
115	              "name": { "type": "string" },
116	              "count": { "type": "integer", "minimum": 1 },
117	              "vramGb": { "type": "number", "minimum": 0 }
118	            }
119	          }
120	        },
121	        "detected": {
122	          "type": "object",
123	          "additionalProperties": false,
124	          "properties": {
125	            "gpuCount": { "type": "integer", "minimum": 0 },
126	            "totalGpuVramGb": { "type": "number", "minimum": 0 },
127	            "systemRamGb": { "type": "number", "minimum": 0 }
128	          }
129	        },
130	        "limits": { "type": "array", "items": { "type": "string" } }
131	      }
132	    },
133	
134	    "execution": {
135	      "type": "object",
136	      "additionalProperties": false,
137	      "properties": {
138	        "maxParallelSlices": { "type": "integer", "minimum": 1 },
139	        "maxConcurrentModels": { "type": "integer", "minimum": 1 },
140	        "contextReservePercent": { "type": "number", "minimum": 0, "maximum": 100 },
141	        "scheduling": { "enum": ["serial-per-model", "throughput", "parallel-batched"] }
142	      }
143	    },
144	
145	    "delegation": {
146	      "type": "object",
147	      "additionalProperties": false,
148	      "properties": {
149	        "preferredTaskTypes": { "type": "array", "items": { "type": "string" } },
150	        "avoidTaskTypes": { "type": "array", "items": { "type": "string" } }
151	      }
152	    },
153	
154	    "model": {
155	      "type": "object",
156	      "required": ["name"],
157	      "additionalProperties": true,
158	      "properties": {
159	        "name": { "type": "string" },
160	        "roles": { "type": "array", "items": { "type": "string" } },
161	        "priority": { "enum": ["high", "medium", "low"] },
162	        "contextWindow": { "type": "integer", "minimum": 1 },
163	        "supportsToolUse": { "type": "boolean" },
164	        "toolCallReliability": { "enum": ["validated", "unverified", "unreliable"] },
165	        "jsonModeReliability": { "enum": ["validated", "unverified", "unreliable"] },
166	        "notes": { "type": "string" }
167	      }
168	    },
169	
170	    "runtime": {
171	      "type": "object",
172	      "required": ["kind", "port"],
173	      "additionalProperties": false,
174	      "properties": {
175	        "kind": {
176	          "enum": ["ollama", "sglang", "llama-cpp", "vllm", "localai"],
177	          "description": "Inference server installed on this machine. Determines API family, provider id, and lane family."
178	        },
179	        "port": { "type": "integer", "minimum": 1, "maximum": 65535 },
180	        "enabled": { "type": "boolean", "default": true },
181	        "primary": { "type": "boolean" },
182	        "reachable": { "type": "boolean" },
183	        "hermesPriority": {
184	          "type": "integer",
185	          "description": "Higher wins in Hermes lane ordering. Ignored by the TypeScript registry, which orders by tier."
186	        },
187	        "notes": { "type": "string" },
188	        "models": { "type": "array", "items": { "$ref": "#/definitions/model" } }
189	      }
190	    },
191	
192	    "machine": {
193	      "type": "object",
194	      "required": ["id", "label", "network", "runtimes"],
195	      "additionalProperties": false,
196	      "properties": {
197	        "id": { "type": "string", "pattern": "^[a-z0-9][a-z0-9-]*$" },
198	        "label": { "type": "string" },
199	        "network": { "$ref": "#/definitions/network" },
200	        "hardware": { "$ref": "#/definitions/hardware" },
201	        "execution": { "$ref": "#/definitions/execution" },
202	        "delegation": { "$ref": "#/definitions/delegation" },
203	        "runtimes": { "type": "array", "items": { "$ref": "#/definitions/runtime" }, "minItems": 1 }
204	      }
205	    },
206	
207	    "aggregator": {
208	      "type": "object",
209	      "required": ["id", "label", "kind", "network", "port"],
210	      "additionalProperties": false,
211	      "properties": {
212	        "id": { "type": "string" },
213	        "label": { "type": "string" },
214	        "kind": { "enum": ["hermes"] },
215	        "network": { "$ref": "#/definitions/network" },
216	        "port": { "type": "integer", "minimum": 1, "maximum": 65535 },
217	        "enabled": { "type": "boolean" },
218	        "notes": { "type": "string" },
219	        "execution": { "$ref": "#/definitions/execution" },
220	        "models": { "type": "array", "items": { "$ref": "#/definitions/model" } }
221	      }
222	    },
223	
224	    "cloudProvider": {
225	      "type": "object",
226	      "required": ["id", "label", "provider", "endpoint"],
227	      "additionalProperties": false,
228	      "properties": {
229	        "id": { "type": "string" },
230	        "label": { "type": "string" },
231	        "provider": { "type": "string" },
232	        "endpoint": { "type": "string" },
233	        "enabled": { "type": "boolean", "default": false },
234	        "notes": { "type": "string" },
235	        "models": { "type": "array", "items": { "$ref": "#/definitions/model" } }
236	      }
237	    }
238	  }
239	}
